pub struct Solution;

use std::collections::HashMap;

impl Solution {
    pub fn group_anagrams(strs: Vec<String>) -> Vec<Vec<String>> {
        let mut map: HashMap<[u8; 26], Vec<String>> = HashMap::new();
        for s in strs {
            let mut count = [0u8; 26];
            for &b in s.as_bytes() {
                count[(b - b'a') as usize] += 1;
            }
            map.entry(count).or_default().push(s);
        }
        map.into_values().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::Solution;

    #[test]
    fn test_group_anagrams_basic() {
        let strs = vec![
            "eat".to_string(),
            "tea".to_string(),
            "tan".to_string(),
            "ate".to_string(),
            "nat".to_string(),
            "bat".to_string(),
        ];
        let mut res = Solution::group_anagrams(strs);
        for group in &mut res {
            group.sort();
        }
        res.sort();

        let expected = vec![
            vec!["ate".to_string(), "eat".to_string(), "tea".to_string()],
            vec!["bat".to_string()],
            vec!["nat".to_string(), "tan".to_string()],
        ];
        assert_eq!(res, expected);
    }

    #[test]
    fn test_empty_string() {
        let strs = vec!["".to_string()];
        let res = Solution::group_anagrams(strs);
        assert_eq!(res, vec![vec!["".to_string()]]);
    }

    #[test]
    fn test_single_char() {
        let strs = vec!["a".to_string()];
        let res = Solution::group_anagrams(strs);
        assert_eq!(res, vec![vec!["a".to_string()]]);
    }
}
